const PROVIDER_IDS: Record<string, string> = { Anthropic: "anthropic", OpenAI: "openai", Google: "google", "Local · Ollama": "ollama" };
/** `provider/id`, the form persona-audit shows model refs in. A model the extension supplies is already keyed that way. */
export function modelRef(id: string): string {
    if (id.includes("/"))
        return id;
    const m = MODELS.find((x) => x.id === id);
    return m ? `${PROVIDER_IDS[m.provider] ?? m.provider.toLowerCase()}/${m.id}` : id;
}
/** `provider/id · level`, as phaseModelChoiceLabel prints it. */
export function choiceLabel(c: ModelChoice): string {
    return c.level ? `${modelRef(c.id)} · ${c.level}` : modelRef(c.id);
}
/** The picker's caution for a no-reasoning pass (thinkingOffWarning). */
export function thinkingOffWarning(model: Model | undefined, level: string | null): string | undefined {
    if (!model)
        return undefined;
    if (model.levels && level !== "off")
        return undefined;
    const lead = model.levels ? "Thinking is turned off for this model" : "This model has no thinking mode";
    return `⚠ ${lead} — it runs in a single pass with no reasoning step, which makes it less reliable at careful multi-step work like landing exact-text edits or judging diffs. A thinking-capable model is recommended.`;
}
